uniform float speed : 0.0 .. 10.0 = 3.0;
uniform float density : 0.0 .. 1.0 = 0.15;
uniform float tail_len : 0.05 .. 0.5 = 0.15;
uniform vec3 tint : color = 0.0, 1.0, 0.3;

state fixed phase;
state fixed speed_fixed;

void update() {
  speed_fixed = fixed(speed);
  phase = fract(phase + speed_fixed * fixed(dt));
}

fixed rand_fixed(fixed x) {
  fixed a = fixed(1664525);
  fixed c = fixed(1013904223);
  fixed m = fixed(4294967296.0);
  fixed res = fract((a * x + c) / m);
  return res;
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed y = s + phase;
  fixed fy = fract(y);

  fixed col = fixed(led.idx);
  fixed seed = rand_fixed(col * fixed(12345.0) + fixed(frame));
  fixed active = step(fixed(density), seed);

  fixed pos_in_strip = fy * active;
  fixed head = fixed(0.0);
  fixed tail = tail_len;

  fixed dist_from_head = head - pos_in_strip;
  if (dist_from_head < fixed(0.0)) dist_from_head = dist_from_head + fixed(1.0);

  fixed brightness = fixed(0.0);
  if (dist_from_head < tail) {
    brightness = fixed(1.0) - dist_from_head / tail;
    brightness = brightness * brightness;
  }

  fixed r = fixed(tint.r) * brightness;
  fixed g = fixed(tint.g) * brightness;
  fixed b = fixed(tint.b) * brightness;

  return vec3(float(r), float(g), float(b));
}

